package com.trampolim.api.geography;
import java.util.*;import org.springframework.web.bind.annotation.*;import org.springframework.beans.factory.annotation.Qualifier;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;import com.trampolim.api.security.PlatformAccess;
@RestController public class RegionalCatalogController {
 private final JdbcTemplate jdbc;private final TerritorialCatalog geo;private final PlatformAccess access;
 public RegionalCatalogController(@Qualifier("jdbcTemplate")JdbcTemplate jdbc,TerritorialCatalog geo,PlatformAccess access){this.jdbc=jdbc;this.geo=geo;this.access=access;}
 public record Assignment(String municipalityCode){}
 @GetMapping("/api/opportunities/{kind}/regional")public Map<String,Object> list(@PathVariable String kind,@RequestParam(defaultValue="")String region,@RequestParam(defaultValue="")String municipalityCode,@RequestParam(defaultValue="true")boolean includeRemote,@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="")String city,@RequestParam(defaultValue="")String area,@RequestParam(defaultValue="")String modality,@RequestParam(defaultValue="9223372036854775807")long before,@RequestParam(defaultValue="20")int limit,@RequestParam Map<String,String> parameters){if(!Set.of("job","course").contains(kind))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Tipo de catálogo inválido.");var filter=RegionalQuery.filter(geo,new RegionalQuery.Filters(region,municipalityCode,includeRemote,q,city,area,modality,before,limit),"l");filter=SearchRefinements.apply(geo,filter,parameters,false);var args=new ArrayList<Object>();args.add(kind);args.addAll(filter.args());args.add(limit+1);var rows=jdbc.queryForList("SELECT l.id,l.kind,l.title,l.provider,l.description,l.url,l.area,l.location,l.municipality_code,l.latitude,l.longitude,l.modality,l.experience_level,l.contract_type,l.work_schedule,l.salary,l.accessibility,l.active,l.expires_at,l.created_at,l.published_at,l.link_status,l.last_link_check_at FROM catalog_items l WHERE l.kind=? AND l.active=TRUE AND l.moderation_status='APPROVED' AND (l.expires_at IS NULL OR l.expires_at>=(CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo')::date)"+filter.where()+" ORDER BY l.id DESC LIMIT ?",args.toArray());var normalized=new ArrayList<Map<String,Object>>();for(var row:rows){var copy=new LinkedHashMap<String,Object>();row.forEach((key,value)->{StringBuilder camel=new StringBuilder();boolean up=false;for(char c:key.toCharArray()){if(c=='_')up=true;else{camel.append(up?Character.toUpperCase(c):c);up=false;}}copy.put(camel.toString(),value instanceof java.sql.Date date?date.toLocalDate().toString():value instanceof java.sql.Timestamp timestamp?timestamp.toInstant().toString():value);});copy.put("municipalityLabel",geo.label(row.get("municipality_code")));normalized.add(copy);}return RegionalQuery.page(normalized,limit);}
 @GetMapping("/api/admin/catalog/{id}/municipality")public Map<String,Object> current(@AuthenticationPrincipal String email,@PathVariable long id){if(!access.isSuperAdmin(email))throw new ResponseStatusException(HttpStatus.FORBIDDEN);var rows=jdbc.queryForList("SELECT municipality_code FROM catalog_items WHERE id=?",id);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND);var result=new LinkedHashMap<String,Object>();result.put("municipality",rows.get(0).get("municipality_code")==null?null:geo.municipality(rows.get(0).get("municipality_code").toString()));return result;}
 @PutMapping("/api/admin/catalog/{id}/municipality")@ResponseStatus(HttpStatus.NO_CONTENT)public void assign(@AuthenticationPrincipal String email,@PathVariable long id,@RequestBody Assignment input){if(!access.isSuperAdmin(email))throw new ResponseStatusException(HttpStatus.FORBIDDEN);if(input==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST);String code=input.municipalityCode();if(code!=null&&!code.isBlank())geo.municipality(code);else code=null;if(jdbc.update("UPDATE catalog_items SET municipality_code=?,updated_at=CURRENT_TIMESTAMP,updated_by=? WHERE id=?",code,email,id)==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND);}
}
